import sys; sys.path.insert(0, sys.argv[1]); from batch_lib import write_batch; from eintenn_routes import ROUTES
E=lambda x: 'place_eintenn_'+x
P=[
('brackenfell','Brackenfell','village',12,38,['wisewoman_hut'],"A turf-cutters’ village on the western moor. Every house has a peat stack taller than its door.",
 [('cuttings','The Peat Cuttings','Black trenches, squared off like graves.'),('stacks','The Stacks','Peat drying in herringbone walls.')],['wisewoman_hut',E('reedmere')],
 ('ortwin','Ortwin Peat','Turf-Cutter of Brackenfell','a stooped man with a long narrow spade',"“Step on the brown, not the green,” he says. “Ortwin Peat. The green is water with a skin on.”","Ortwin once cut a pair of boots out of the moor, a thousand years old and better made than his.","“It burns slow and it burns all night,” Ortwin says. “Like a grudge.”",'cuttings','stacks'),
 ('cut_peat','Cut peat','Spade down, lever, lift, and lay it to dry.','cuttings',6,16,2,'skill_athletics',None)),
('standing_sisters','The Standing Sisters','wild',10,26,['greenwife_grove'],"Three leaning stones on a rise, tied with rags by people who would not say why. The grass inside them is never grazed.",
 [('stones','The Three Stones','Grey, lichened, and warmer than they should be.'),('thorn','The Rag Thorn','A thorn tree heavy with knotted cloth.')],['greenwife_grove','brackenfell'],
 ('gundel','Mother Gundel','Keeper of the Sisters','an old woman untying faded rags and tying on fresh ones',"“Do not walk between them,” she says, not unkindly. “Round. Mother Gundel. I keep count of the wishes.”","Mother Gundel says the stones lean a finger further each year, toward each other.","“People ask them for small things,” she says. “That is why it works.”",'thorn','stones'),
 ('gather_moor_herbs','Gather by the stones','What grows inside the ring is not what grows outside it.','stones',6,12,1,'skill_herblore',12)),
('cloudgate_pass','Cloudgate Pass','wild',18,8,['hohenkamm','thunder_caves'],"The notch in the ridge where the track crosses the Hohenkamm. It is open four months in the year, and the cairns are there for the other eight.",
 [('cairns','The Cairns','A line of stone piles, each a rope’s length from the last.'),('shelter','The Stone Shelter','Four walls, half a roof and a stack of someone else’s firewood.')],['hohenkamm','thunder_caves',E('high_byre')],
 ('falk','Falk Scree','Guide of the Pass','a lean man watching a cloud as if it had spoken',"“Not today,” he says, before you ask. “Falk Scree. Tomorrow before noon, or not at all.”","Falk leaves firewood in the shelter every autumn and has never found out who uses it.","“The mountain does not hate you,” Falk says. “It has not noticed you.”",'shelter','cairns'),
 ('mend_cairns','Mend the cairns','Stone on stone, high enough to show above snow.','cairns',7,14,2,'skill_wayfaring',None)),
('the_antler','The Antler','site',26,32,['grauwald'],"A foresters’ alehouse just inside the Grauwald. Every beam has horns nailed to it, and every horn has a story that gets longer.",
 [('taproom','The Taproom','Low, smoky and loud after dark.'),('woodyard','The Woodyard','Cut logs, a chopping block and a dog.')],['grauwald',E('burners_ride'),'greenwife_grove'],
 ('imke','Imke Spile','Alewife of the Antler','a red-armed woman carrying four mugs in each hand',"She puts eight mugs down without spilling. “Imke Spile. Sit anywhere that is not under the big one. It falls.”","Imke settles every argument about who shot what by pointing at the wall.","“Foresters drink like men who work alone,” Imke says. “All at once.”",'taproom','woodyard'),
 ('split_logs','Split logs for the fire','Axe, block, and a rhythm you can keep.','woodyard',7,17,1,'skill_woodcraft',None)),
('mossbeck','Mossbeck','village',16,34,['grauwald','wisewoman_hut'],"A village of basket-makers on a willow stream. Half the eel-traps, bee-skeps and cradles in the west were woven here.",
 [('osiers','The Osier Beds','Willow cut to the stump and grown again.'),('doorsteps','The Doorsteps','Where the weaving is done, in the light.')],['brackenfell','the_antler','wisewoman_hut'],
 ('tilo','Tilo Wand','Basket-Maker of Mossbeck','a man weaving without looking at his hands',"His hands keep going. “Tilo Wand. Ask me anything. They do not need me for this part.”","Tilo makes a cradle for every child born in the village and a creel for every man who dies.","“Willow forgives,” Tilo says. “Oak holds a grudge.”",'doorsteps','osiers'),
 ('strip_osiers','Strip osiers','Pull each rod through the brake until it comes out white.','osiers',7,16,2,'skill_woodwork',None)),
('silverford','Silverford','village',48,34,['silberhalde','tennfels'],"The ford where the ore carts cross on their way to the castle and the coast. A wheelwright, a smith and an inn live off broken axles.",
 [('ford','The Ford','A paved crossing, rutted a hand deep.'),('wrights','The Wrights’ Yard','Wheels in every stage of becoming round.')],['silberhalde',E('black_quarry'),E('slag_heaps')],
 ('arno','Arno Axle','Wheelwright of Silverford','a man rolling a wheel along with one finger',"He lets the wheel lean against you. “Hold that. Arno Axle. An ore cart breaks here every day. I thank the Duke’s roads.”","Arno can tell a carter’s temper from the wear on his wheels.","“Round is easy,” Arno says. “Round and true is the trade.”",'wrights','ford'),
 ('shape_spokes','Shape spokes','Spokeshave and a good eye, twelve to a wheel.','wrights',7,17,2,'skill_woodwork',None)),
('burgmill','Burgmill','site',44,43,['tennfels'],"The castle’s mill under the rock of Tennfels. The Duke’s tenants must bring their corn here and nowhere else, by law.",
 [('stones','The Mill Floor','Two pairs of stones and a miller who weighs twice.'),('race','The Mill Race','Fast water in a stone channel.')],['tennfels',E('hanging_oak')],
 ('veit','Veit Grist','Miller of the Burgmill','a man with flour in his eyebrows and a short measure in his hand',"“Castle corn first,” he says. “Then yours. Veit Grist. I did not make the law, I only like it.”","Veit knows the size of every holding on the demesne by the sacks that come from it.","“They must come here,” Veit says. “So I need not be pleasant.”",'stones','race'),
 ('dress_stones','Dress the millstones','Pick and bill, furrow by furrow, with grit in your teeth.','stones',7,15,2,'skill_building',None)),
('rabenstein','Rabenstein','site',58,26,['silberhalde','wp_ferry'],"A broken watchtower on a crag, with a beacon basket still kept filled. Ravens nest in what is left of the top floor.",
 [('tower','The Tower','Three floors, two of them open to the sky.'),('beacon','The Beacon','An iron basket of dry furze under a tarred hood.')],[E('lindenau'),'vaelis_ruins'],
 ('wolfram','Wolfram Ember','Beacon-Keeper of Rabenstein','a grey man feeding a raven from his hand',"“He bites,” he says, as the raven does not. “Wolfram Ember. I have kept this fire ready thirty years and lit it once.”","Wolfram will not say what the once was for.","“A beacon is a promise,” Wolfram says. “Mostly you keep it by doing nothing.”",'beacon','tower'),
 ('cut_furze','Cut furze for the beacon','Gloves, a hook and a bundle bigger than you are.','beacon',7,16,2,'skill_woodcraft',None)),
('nordwick','Nordwick','village',70,22,['wp_ferry'],"A river hamlet upstream of the ferry, where salmon are netted in the run and salted for the rest of the year.",
 [('staithe','The Staithe','A plank landing and six flat boats.'),('saltsheds','The Salting Sheds','Split fish in rows, grey with salt.')],['wp_ferry',E('osterau'),'rabenstein'],
 ('elke','Elke Roe','Fisher of Nordwick','a woman knee-deep in the river with a hand-net',"“Stand still,” she says. “You are frightening my supper.” Later: “Elke Roe. They only run a fortnight. Then we wait.”","Elke says the salmon come back to the very gravel they were born on, and that people are the same.","“You cannot hurry the run,” Elke says. “You can only be here.”",'staithe','saltsheds'),
 ('salt_fish','Salt the catch','Split, gut, pack in salt, and turn the barrel.','saltsheds',8,17,2,'skill_fishing',None)),
('chainhouse','The Chainhouse','site',90,26,['wp_ferry'],"The far-bank house where the ferry’s chain is winched. Four men and a horse walk the capstan every time the horn sounds.",
 [('capstan','The Capstan','A drum as tall as a man, wound with wet chain.'),('landing','The Far Landing','Mud, planks and the road going on east.')],['wp_ferry'],
 ('udo','Udo Winch','Chainman of the Ferry','a thick-necked man leaning on a capstan bar',"“When the horn goes, push,” he says. “Udo Winch. When it goes twice, push harder.”","Udo has crossed the river ten thousand times and never been to the other side’s village.","“The ferryman takes the coin,” Udo says. “I take the river.”",'capstan','landing'),
 ('walk_capstan','Walk the capstan','Chest to the bar, and round, and the ferry comes.','capstan',6,20,2,'skill_athletics',None)),
('sandhaven','Sandhaven','village',92,50,['kess_fondaco','kess_harbor'],"A pilots’ hamlet on the dunes east of the town. They row out to meet anything with a foreign rig and bring it in over the bar.",
 [('dunes','The Lookout Dune','A pole, a flag and a boy with good eyes.'),('boats','The Pilot Boats','Clinker-built, tarred, and always bows-out.')],['kess_fondaco',E('long_reach')],
 ('kai','Kai Lead','Pilot of Sandhaven','a man squinting at a sail nobody else can see yet',"“Marrean,” he says, of a speck. “Deep-laden. Kai Lead. First boat out gets the fee.”","Kai knows the bar the way Ostwick farmers know their strips.","“The sand moves every storm,” Kai says. “The charts are a year behind. I am not.”",'dunes','boats'),
 ('watch_bar','Watch for sails','Eyes on the edge of the sea, and shout the rig.','dunes',5,19,2,'skill_seamanship',12)),
('pitch_kilns','The Pitch Kilns','site',86,64,['kess_harbor'],"Kilns east of the shipyard where pine is burned down to tar. The smoke is why nobody else lives on that side.",
 [('kilns','The Kilns','Turf-covered mounds that drip black.'),('barrels','The Tar Barrels','Rows of barrels nobody leans on twice.')],['kess_harbor','sandhaven',E('netmenders_strand')],
 ('rike','Rike Kettle','Tar-Boiler of the Kilns','a woman black to the elbow, stirring with a paddle',"“Do not touch anything,” she says. “Including me. Rike Kettle.”","Rike says every ship out of Kesselhaven floats on her work and smells of it too.","“Tar keeps the sea out,” Rike says. “And company.”",'kilns','barrels'),
 ('tend_kiln','Tend a kiln','Keep it smouldering, never burning, and watch the run.','kilns',6,18,3,'skill_kilncraft',None)),
('herring_stairs','The Herring Stairs','site',78,66,['kess_harbor','kess_market'],"Wide steps down to the water where the herring boats sell straight off the gunwale. By noon it is scales and gulls.",
 [('steps','The Steps','Slick, crowded and loud.'),('barrow_rank','The Barrow Rank','Hand-barrows waiting for a load to wheel uphill.')],['kess_harbor',E('salters_gate')],
 ('meta','Meta Scale','Fish-Seller of the Stairs','a woman shouting a price and dropping it as she shouts',"“Six! Five and a half!” She looks at you. “Meta Scale. Four to you if you take the barrel.”","Meta says the price of herring is whatever the last boat in will take.","“By noon it is cat-food,” Meta says. “So I talk fast.”",'steps','barrow_rank'),
 ('wheel_barrows','Wheel herring up the hill','A full barrow, a steep street, and a fair penny at the top.','barrow_rank',6,12,1,'skill_trade',None)),
('lantern_court','Lantern Court','site',64,63,['kess_undercroft','kess_market'],"A yard of lamp-oil sellers above the Undercroft, and the watch-house of the night patrol. It is the last lit place before the streets that are not.",
 [('watchhouse','The Watch-House','A bench, a rack of staves and a slate of streets.'),('oilshops','The Oil Shops','Jars, wicks and a smell of fish.')],['kess_undercroft','kess_market'],
 ('volker','Volker Wick','Night-Watchman of the Court','a heavy man lighting a lantern from another lantern',"“Curfew is for other people,” he says. “You are other people. Volker Wick.”","Volker knows which doors in the Undercroft to knock on and which to walk past.","“I am paid to be seen,” Volker says. “Catching anyone is extra.”",'watchhouse','oilshops'),
 ('walk_rounds','Walk the rounds','Lantern high, stave low, and call the hour at each corner.','watchhouse',19,23,2,'skill_streetwise',None)),
('bleaching_fields','The Bleaching Fields','site',56,62,['kess_market'],"Meadows south-west of the town where new linen is pegged out to whiten. From the walls it looks like snow that has been ironed.",
 [('greens','The Greens','Cloth in long strips, pegged at the corners.'),('lyehouse','The Lye-House','Vats of ash-water and red hands.')],['kess_undercroft',E('eelwater'),E('inkwell_row')],
 ('ilse','Ilse White','Bleacher of the Fields','a woman sprinkling a strip of linen from a can',"“Mind the cloth!” Then, calmer: “Ilse White. Sun, water and time. And no boots.”","Ilse can tell Osterau linen from any other by how fast it whitens.","“Six weeks to turn it white,” Ilse says. “One muddy dog to turn it back.”",'greens','lyehouse'),
 ('water_linen','Water the linen','Along each strip with the can, and never let it dry in the sun.','greens',6,18,2,'skill_clothwork',None)),
('mittelau','Mittelau','village',44,62,['ostwick','aschau'],"A hop-growing village half-way between Ostwick and the wine country. The poles stand in rows like a leafless wood all winter.",
 [('gardens','The Hop Gardens','Poles, strings and green climbing both.'),('kiln','The Drying Kiln','A round kiln with a cowl that turns with the wind.')],[E('three_ash_ford'),E('steinwick'),E('beacon_knoll')],
 ('jorg','Jorg Bine','Hop-Grower of Mittelau','a man on stilts tying a string to the top of a pole',"He looks down. “Jorg Bine. Yes, stilts. You try reaching it.”","Jorg says the brewers of Kesselhaven would be selling sweet barley-water without him.","“Ale is my hops and somebody else’s credit,” Jorg says.",'gardens','kiln'),
 ('string_hops','String the hop poles','Ground to pole-top and down again, four strings to a hill.','gardens',6,16,2,'skill_husbandry',None)),
('sonnhalde','Sonnhalde','village',40,78,['aschau','pomerell'],"A south-facing slope of terraces between the wine country and the abbey. The walls hold the day’s heat for the grapes at night.",
 [('terraces','The Terraces','Dry-stone steps of vines, a man’s height each.'),('hut','The Vine-Watcher’s Hut','A hut on the top wall with a rattle for the birds.')],['aschau',E('appleford'),E('vintners_halt')],
 ('regine','Regine Prune','Vine-Dresser of Sonnhalde','a woman with a curved knife, cutting more off a vine than she leaves',"“It looks cruel,” she says, cutting. “Regine Prune. A vine left alone makes leaves. I want grapes.”","Regine rebuilds a stretch of wall every winter and says the hill is trying to lie down.","“Poor soil, good wine,” Regine says. “It is the only thing poor soil is good for.”",'terraces','hut'),
 ('mend_terrace','Mend a terrace wall','Stone on stone with no mortar, and each one chosen.','terraces',7,16,2,'skill_building',None)),
('southmere','Southmere','village',14,76,['pomerell'],"A reed-cutters’ village on a shallow lake. Every roof for a day’s walk is thatched from here.",
 [('reedbeds','The Reed Beds','Head-high reed, and paths only the cutters know.'),('stacks','The Bundle Stacks','Reed tied in sheaves, butt-ends down.')],[E('bee_garth'),E('sallowfield')],
 ('hanno','Hanno Reed','Reed-Cutter of Southmere','a man in a flat boat, cutting below the waterline with a long hook',"“Winter work,” he says. “When the leaf is off. Hanno Reed. You have come at the right time or the wrong one.”","Hanno says a good reed roof outlasts the man who laid it and the man who paid.","“Straw is for barns,” Hanno says.",'reedbeds','stacks'),
 ('bundle_reed','Bundle reed','Comb it, butt it level on the board, and tie it twice.','stacks',7,16,2,'skill_building',None)),
('red_scar','The Red Scar','wild',8,60,['wisewoman_hut'],"A cliff of red stone with a cell cut into it half-way up. A basket goes down on a rope each morning and comes up with bread or without.",
 [('foot','The Foot of the Scar','A flat stone where people leave things.'),('cell','The Cell','One room, one window, reached by a ladder that is usually drawn up.')],[E('greywater_weir'),'brackenfell'],
 ('wido','Brother Wido','Recluse of the Red Scar','a thin man lowering a basket on a rope, very slowly',"A voice from above: “If it is advice, I have none. If it is bread, thank you. Brother Wido.”","Wido came up for a week of quiet, eleven years ago.","“I do not dislike people,” Wido says. “I like them better from here.”",'cell','foot'),
 ('fill_basket','Fill the hermit’s basket','Bread, an onion, and a question on a scrap of bark.','foot',6,10,1,'skill_devotion',None)),
('westmark_stone','Westmark Stone','site',4,46,['wisewoman_hut'],"The boundary stone of the Duchy on the west road, with a customs hut beside it. The stone has the Duke’s salt-pan on one face and nothing on the other.",
 [('stone','The Stone','Shoulder-high, and worn where carters touch it for luck.'),('hut','The Customs Hut','A bar across the road and a man who lifts it.')],['brackenfell','red_scar'],
 ('benno','Benno Bar','Border-Rider of the Westmark','a rider asleep in the saddle, on a horse that is wide awake',"The horse nudges him. “Hm. Benno Bar. Anything to declare? No? Good. I hate the ledger.”","Benno says more goes round the stone than past it, and that he is not paid enough to mind.","“The Duchy stops here,” Benno says. “The mud keeps going.”",'hut','stone'),
 ('lift_bar','Keep the bar','Lift it for carts, count the wheels, and ask what is under the canvas.','hut',6,19,2,'skill_wayfaring',None)),
]
write_batch(sys.argv[2] if len(sys.argv) > 2 else '.', 'eintenn', 'eintenn-03', P, "Eintenn, third batch: twenty small places in the west, the hills, the river and round Kesselhaven.", routes=ROUTES)
